"""Writing and reading OpenFOAM's ASCII dictionaries and lists (the case is always written in ASCII)."""
from __future__ import annotations

import os
import re

import numpy as np

_NUM = re.compile(r"[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?")


def header(cls: str, obj: str, location: str = "") -> str:
    loc = f'    location    "{location}";\n' if location else ""
    return ("/*--------------------------------*- C++ -*----------------------------------*\\\n"
            "  Generated by Elmer Studio for OpenFOAM v2106\n"
            "\\*---------------------------------------------------------------------------*/\n"
            f"FoamFile\n{{\n    version     2.0;\n    format      ascii;\n    class       {cls};\n{loc}"
            f"    object      {obj};\n}}\n\n")


def fmt(v) -> str:
    if isinstance(v, (list, tuple, np.ndarray)):
        return "(" + " ".join(fmt(x) for x in v) + ")"
    return f"{float(v):.12g}"


def field_value(v, n: int | None = None) -> str:
    """'uniform v' or 'nonuniform List<type> n (...)' for per-face/per-cell arrays."""
    a = np.asarray(v, float)
    if a.ndim == 0 or (a.ndim == 1 and n is None):
        return f"uniform {fmt(a)}"
    if a.ndim == 1:                                  # one scalar per face/cell
        if np.allclose(a, a[0], rtol=0, atol=0):
            return f"uniform {fmt(a[0])}"
        return f"nonuniform List<scalar> {len(a)}\n(\n" + "\n".join(fmt(x) for x in a) + "\n)"
    if np.all(a == a[0]):
        return f"uniform {fmt(a[0])}"
    kind = "vector" if a.shape[1] == 3 else "symmTensor"
    return f"nonuniform List<{kind}> {len(a)}\n(\n" + "\n".join(fmt(x) for x in a) + "\n)"


def write(path: str, text: str):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", newline="\n") as f:
        f.write(text)


# --------------------------------------------------------------------------- reading
def _strip(text: str) -> str:
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.S)
    text = re.sub(r"//[^\n]*", "", text)
    return re.sub(r"FoamFile\s*\{.*?\}", "", text, count=1, flags=re.S)


def read_text(path: str) -> str:
    with open(path, errors="replace") as f:
        return _strip(f.read())


def read_list(path: str, width: int = 1, dtype=float) -> np.ndarray:
    """A top-level list file (points, owner, neighbour): 'N ( ... )' with *width* numbers per item."""
    nums = _NUM.findall(read_text(path))
    if not nums:
        return np.zeros((0, width) if width > 1 else 0, dtype)
    n = int(float(nums[0]))
    vals = np.array(nums[1:1 + n * width], dtype=float)
    if len(vals) != n * width:
        raise ValueError(f"{path}: expected {n * width} values, found {len(vals)}")
    vals = vals.astype(dtype)
    return vals.reshape(n, width) if width > 1 else vals


def read_faces(path: str) -> np.ndarray:
    """polyMesh/faces of an all-quadrilateral mesh: (nFaces, 4)."""
    nums = _NUM.findall(read_text(path))
    n = int(nums[0])
    a = np.array(nums[1:1 + 5 * n], dtype=np.int64).reshape(n, 5)
    if np.any(a[:, 0] != 4):
        raise ValueError(f"{path}: the mesh has faces that are not quadrilaterals")
    return a[:, 1:]


def read_boundary(path: str) -> list[dict]:
    """polyMesh/boundary: [{name, type, nFaces, startFace}] in file order."""
    text = read_text(path)
    out = []
    for m in re.finditer(r"(\w+)\s*\{([^{}]*)\}", text):
        body = m.group(2)
        g = lambda k: (re.search(rf"\b{k}\s+([^;]+);", body) or [None, ""])[1].strip()  # noqa: E731
        out.append({"name": m.group(1), "type": g("type"), "nFaces": int(g("nFaces") or 0),
                    "startFace": int(g("startFace") or 0)})
    return out


def read_cell_zones(path: str) -> dict:
    """polyMesh/cellZones: {zone name: cell labels}."""
    if not os.path.isfile(path):
        return {}
    text = read_text(path)
    out = {}
    for m in re.finditer(r"(\w+)\s*\{\s*type\s+cellZone\s*;\s*cellLabels\s+(?:List<label>\s*)?(\d+)\s*([({])",
                         text):
        n = int(m.group(2))
        if m.group(3) == "{":                         # n{value}: all equal
            v = int(_NUM.match(text, m.end()).group(0))
            out[m.group(1)] = np.full(n, v, np.int64)
            continue
        nums = _NUM.findall(text[m.end():m.end() + 24 * n + 64])
        out[m.group(1)] = np.array(nums[:n], dtype=np.int64)
    return out


def read_internal_field(path: str, width: int) -> tuple[np.ndarray | None, float | np.ndarray | None]:
    """internalField of a vol field: (array, None) when nonuniform, (None, value) when uniform."""
    text = read_text(path)
    m = re.search(r"internalField\s+(uniform|nonuniform)\s+", text)
    if m is None:
        raise ValueError(f"{path}: no internalField")
    rest = text[m.end():]
    if m.group(1) == "uniform":
        if width == 1:
            return None, float(_NUM.match(rest.lstrip()).group(0))
        vals = _NUM.findall(rest[:rest.index(")") + 1])
        return None, np.array(vals[:width], float)
    mm = re.match(r"\s*List<\w+>\s*(\d+)\s*\(", rest)
    if mm is None:                                    # e.g. 'nonuniform List<scalar> 0()'
        return np.zeros((0, width) if width > 1 else 0), None
    n = int(mm.group(1))
    nums = _NUM.findall(rest[mm.end():rest.index(";", mm.end()) if ";" in rest[mm.end():] else None])
    vals = np.array(nums[:n * width], float)
    if len(vals) != n * width:
        raise ValueError(f"{path}: internalField has {len(vals)} of {n * width} values")
    return (vals.reshape(n, width) if width > 1 else vals), None
